        #2;
        // q should still hold previous cycle's value (8'h84)
        if (q !== 8'h84) errors = errors + 1;

        // Now capture the 8'hCC on the next clock edge
        @(posedge clk);
        #1;
        if (q !== 8'hCC) errors = errors + 1;

        // Final result reporting
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
